try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
    IntStream.range(0, 10_000).forEach(i -> {
        executor.submit(() -> {
            Thread.sleep(Duration.ofMillis(1000)); // Non-blocking unmount under the hood
            return fetchRemoteData(i);
        });
    });
} // Executor auto-closes and awaits completion of all virtual threads
